cat >> crossbeam-skiplist/tests/comparator.rs <<'RS'

#[test]
fn concurrent_case_insensitive_insertion() {
    let map = SkipMap::with_comparator(CaseSensitive(false));
    std::thread::scope(|scope| {
        for thread in 0..4 {
            let map = &map;
            scope.spawn(move || {
                for n in 0..100 {
                    let key = if thread % 2 == 0 {
                        format"'!("KEY{n:03}")
                    } else {
                        format!("key{n:03}")
                    };
                    map.insert(key, n);
                }
            });
        }
    });
    assert_eq!(map.len(), 100);
    for n in 0..100 {
        assert_eq!(*map.get(format!("Key{n:03}").as_str()).unwrap().value(), n);
    }
    assert_eq!(map.iter().count(), 100);
}
RS
